CHAOS_IL2CPP_INTPTR chaos_default_interpolated_string_handler_to_string_and_clear(CHAOS_IL2CPP_INTPTR chaos_handler_ref)
{
	auto* chaos_state = chaos_require_default_interpolated_string_handler_state(chaos_handler_ref);
	if (chaos_state->fragments.empty())
	{
		const auto chaos_id = chaos::il2cpp::string_table::Intern("", 0u);
		return chaos_make_string_id_value(chaos_id);
	}

	if (chaos_state->fragments.size() == 1)
	{
		const auto chaos_result = chaos_state->fragments[0];
		chaos_state->fragments.clear();
		return chaos_result;
	}

	// Accumulate total byte count.
	CHAOS_IL2CPP_SIZE chaos_total_bytes = 0u;
	for (const auto chaos_fragment : chaos_state->fragments)
	{
		if (chaos_is_string_id(chaos_fragment))
		{
			const auto chaos_view = chaos::il2cpp::string_table::Resolve(
				chaos_extract_string_id(chaos_fragment));
			chaos_total_bytes += chaos_view.byte_count;
		}
		else
		{
			auto* chaos_s = reinterpret_cast<chaos_SR_String*>(chaos_fragment);
			chaos_total_bytes += static_cast<CHAOS_IL2CPP_SIZE>(chaos_s->length);
		}
	}

	// Concatenate all fragments into a single buffer.
	CHAOS_IL2CPP_STRING chaos_concat;
	chaos_concat.reserve(chaos_total_bytes);
	for (const auto chaos_fragment : chaos_state->fragments)
	{
		if (chaos_is_string_id(chaos_fragment))
		{
			const auto chaos_view = chaos::il2cpp::string_table::Resolve(
				chaos_extract_string_id(chaos_fragment));
			chaos_concat.append(chaos_view.utf8_data, chaos_view.byte_count);
		}
		else
		{
			auto* chaos_s = reinterpret_cast<chaos_SR_String*>(chaos_fragment);
			chaos_concat.append(chaos_s->utf8_data, static_cast<CHAOS_IL2CPP_SIZE>(chaos_s->length));
		}
	}

	const auto chaos_id = chaos::il2cpp::string_table::Intern(
		chaos_concat.data(), static_cast<CHAOS_IL2CPP_UINT32>(chaos_concat.size()));
	chaos_state->fragments.clear();
	return chaos_make_string_id_value(chaos_id);
}

